function e($v){return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');}function token(){if(empty($_SESSION['csrf']))$_SESSION['csrf']=bin2hex(random_bytes(24));return $_SESSION['csrf'];}function toman($n){return number_format((int)$n).' تومان';}
$orderId=max(0,(int)($_REQUEST['order_id']??0));$msg='';$err='';
function recalc_order(PDO $pdo,int $orderId): void {$s=$pdo->prepare('SELECT COALESCE(SUM(unit_price*quantity),0) FROM order_items WHERE order_id=?');$s->execute([$orderId]);$sub=(int)$s->fetchColumn();$q=$pdo->prepare('SELECT delivery_fee,status FROM orders WHERE id=?');$q->execute([$orderId]);$o=$q->fetch();if(!$o)return;$status=(string)$o['status']==='ready'?'preparing':(string)$o['status'];$pdo->prepare('UPDATE orders SET subtotal=?,total=?,status=?,status_updated_at=NOW(),pyramid_synced_at=NULL,pyramid_invoice_no=NULL WHERE id=?')->execute([$sub,$sub+(int)$o['delivery_fee'],$status,$orderId]);}
if($_SERVER['REQUEST_METHOD']==='POST'){
 if(!hash_equals($_SESSION['csrf']??'',$_POST['csrf']??'')){ts_html_fail('REQ-102',419,'index.php');}
 $action=(string)($_POST['action']??'');$itemId=max(0,(int)($_POST['item_id']??0));
 try{$pdo->beginTransaction();$q=$pdo->prepare("SELECT status FROM orders WHERE id=? FOR UPDATE");$q->execute([$orderId]);$status=(string)($q->fetchColumn()?:'');if($status===''||in_array($status,['cancelled','delivered'],true))throw new RuntimeException('این سفارش دیگر قابل اصلاح نیست.');
   $q=$pdo->prepare('SELECT * FROM order_items WHERE id=? AND order_id=? FOR UPDATE');$q->execute([$itemId,$orderId]);$it=$q->fetch();if(!$it)throw new RuntimeException('قلم سفارش پیدا نشد.');
   if($action==='qty'){
     $new=max(0,min(99,(int)($_POST['quantity']??0)));$old=(int)$it['quantity'];$diff=$new-$old;
     if($new===0){$pdo->prepare('UPDATE products SET stock=stock+?,updated_at=NOW() WHERE id=?')->execute([$old,(int)$it['product_id']]);$pdo->prepare('DELETE FROM order_items WHERE id=?')->execute([$itemId]);$msg='قلم حذف شد و موجودی برگشت.';}
     else{if($diff>0){$p=$pdo->prepare('SELECT stock FROM products WHERE id=? FOR UPDATE');$p->execute([(int)$it['product_id']]);$stock=(int)$p->fetchColumn();if($stock<$diff)throw new RuntimeException('موجودی برای افزایش تعداد کافی نیست.');$pdo->prepare('UPDATE products SET stock=stock-?,updated_at=NOW() WHERE id=?')->execute([$diff,(int)$it['product_id']]);}elseif($diff<0){$pdo->prepare('UPDATE products SET stock=stock+?,updated_at=NOW() WHERE id=?')->execute([-1*$diff,(int)$it['product_id']]);}$pdo->prepare("UPDATE order_items SET quantity=?,picked=0,picked_at=NULL,adjustment_note=CONCAT('تعداد اصلاح شد: ',?) WHERE id=?")->execute([$new,$old.' ← '.$new,$itemId]);$msg='تعداد اصلاح شد.';}
   } elseif($action==='substitute'){
     $newPid=max(0,(int)($_POST['product_id']??0));if($newPid<1||(int)$it['product_id']===$newPid)throw new RuntimeException('کالای جایگزین معتبر نیست.');$p=$pdo->prepare('SELECT id,name,barcode,price,stock,active FROM products WHERE id=? FOR UPDATE');$p->execute([$newPid]);$np=$p->fetch();$qty=(int)$it['quantity'];if(!$np||(int)$np['active']!==1||(int)$np['price']<1||(int)$np['stock']<$qty)throw new RuntimeException('کالای جایگزین فعال نیست یا موجودی کافی ندارد.');
     $pdo->prepare('UPDATE products SET stock=stock+?,updated_at=NOW() WHERE id=?')->execute([$qty,(int)$it['product_id']]);$pdo->prepare('UPDATE products SET stock=stock-?,updated_at=NOW() WHERE id=?')->execute([$qty,$newPid]);
     $origName=(string)($it['original_product_name']?:$it['product_name']);$note='جایگزین «'.$origName.'» شد';$pdo->prepare('UPDATE order_items SET product_id=?,barcode=?,product_name=?,unit_price=?,picked=0,picked_at=NULL,adjustment_note=? WHERE id=?')->execute([$newPid,$np['barcode'],$np['name'],(int)$np['price'],$note,$itemId]);$msg='کالای جایگزین ثبت و مبلغ سفارش اصلاح شد.';
   } else throw new RuntimeException('عملیات نامعتبر است.');
   recalc_order($pdo,$orderId);$pdo->commit();ts_audit($pdo,'order_adjusted','order='.$orderId.' item='.$itemId.' action='.$action);
 }catch(Throwable $x){if($pdo->inTransaction())$pdo->rollBack();$err=ts_error_text('SYS-100');ts_log_internal($x,'SYS-100');}
}
$st=$pdo->prepare('SELECT o.*,c.name customer_name,c.phone,c.address FROM orders o JOIN customers c ON c.id=o.customer_id WHERE o.id=?');$st->execute([$orderId]);$order=$st->fetch();if(!$order){http_response_code(404);exit('سفارش پیدا نشد.');}
$st=$pdo->prepare('SELECT oi.*,p.stock current_stock,p.image_path FROM order_items oi LEFT JOIN products p ON p.id=oi.product_id WHERE oi.order_id=? ORDER BY oi.id');$st->execute([$orderId]);$items=$st->fetchAll();
$products=$pdo->query("SELECT id,name,brand,quantity_label,price,stock FROM products WHERE active=1 AND price>0 AND stock>0 ORDER BY name LIMIT 800")->fetchAll();
?><!doctype html><html lang="fa" dir="rtl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>اصلاح سفارش #<?=(int)$orderId?></title><link rel="stylesheet" href="assets/style.css"><style>.wrap{max-width:900px;margin:20px auto;padding:0 12px}.item{background:#fff;border:1px solid #e5ece6;border-radius:16px;padding:13px;margin:10px 0}.row{display:grid;grid-template-columns:70px 1fr;gap:12px}.row img{width:64px;height:64px;object-fit:contain}.forms{display:grid;grid-template-columns:1fr 2fr;gap:8px;margin-top:10px}.forms form{display:flex;gap:7px;align-items:end}.forms input,.forms select{min-width:0}.warn{background:#fff8e8;padding:10px;border-radius:10px}@media(max-width:700px){.forms{grid-template-columns:1fr}.forms form{display:grid;grid-template-columns:1fr auto}}</style></head><body><header class="top"><a class="brand" href="admin_orders.php"><span class="logo">🧺</span><span><b>اصلاح سفارش #<?=(int)$orderId?></b><small>حذف، تغییر تعداد یا جایگزینی</small></span></a><a class="btn pale" href="admin_orders.php#order-<?=(int)$orderId?>">بازگشت</a></header><main class="wrap"><?php if($msg):?><div class="success"><?=e($msg)?></div><?php endif;?><?php if($err):?><div class="notice"><?=e($err)?></div><?php endif;?><section class="panel"><h2><?=e($order['customer_name'])?> · <?=e($order['phone'])?></h2><p><?=e($order['address'])?></p><p><b>جمع فعلی:</b> <?=toman($order['total'])?></p><div class="warn">هر تغییری در تعداد یا جایگزینی، موجودی کالا و مبلغ سفارش را همان لحظه اصلاح می‌کند.</div></section><?php foreach($items as $it):?><div class="item"><div class="row"><?php if($it['image_path']):?><img src="<?=e($it['image_path'])?>" alt=""><?php else:?><div style="font-size:40px">🛒</div><?php endif;?><div><b><?=e($it['product_name'])?></b><div class="muted"><?=number_format((int)$it['quantity'])?> عدد × <?=toman($it['unit_price'])?> · موجودی فعلی <?=number_format((int)($it['current_stock']??0))?></div><?php if($it['adjustment_note']):?><div class="muted"><?=e($it['adjustment_note'])?></div><?php endif;?></div></div><div class="forms"><form method="post"><input type="hidden" name="csrf" value="<?=e(token())?>"><input type="hidden" name="action" value="qty"><input type="hidden" name="order_id" value="<?=(int)$orderId?>"><input type="hidden" name="item_id" value="<?=(int)$it['id']?>"><label>تعداد جدید<input type="number" name="quantity" min="0" max="99" value="<?=(int)$it['quantity']?>"></label><button class="btn">ذخیره تعداد</button></form><form method="post"><input type="hidden" name="csrf" value="<?=e(token())?>"><input type="hidden" name="action" value="substitute"><input type="hidden" name="order_id" value="<?=(int)$orderId?>"><input type="hidden" name="item_id" value="<?=(int)$it['id']?>"><label>جایگزین<select name="product_id" required><option value="">انتخاب کالا…</option><?php foreach($products as $p):if((int)$p['id']===(int)$it['product_id'])continue;?><option value="<?=(int)$p['id']?>"><?=e($p['name'].' '.trim(($p['brand']??'').' '.($p['quantity_label']??'')).' · '.number_format((int)$p['price']).' · موجودی '.(int)$p['stock'])?></option><?php endforeach;?></select></label><button class="btn">جایگزین کن</button></form></div></div><?php endforeach;?></main></body></html>
